# frozen_string_literal: true

require "rails_helper"

RSpec.describe OutboxSnapshot do
  it "answers each company's own oldest unsent enqueue time and leaves out companies with nothing unsent" do
    now = Time.utc(2026, 4, 1, 12)
    insert_row = lambda do |company_id, enqueued_at, sent_at: nil|
      OutboxSnapshot.insert_all!([{
        "id" => 70 + company_id, "project_id" => 5, "user_id" => 6, "work_date" => Date.new(2026, 3, 2),
        "duration" => 60.0, "bill_status" => "unbilled", "review_status" => "not_required", "locked" => false,
        "source" => "manual", "source_metadata" => {}, "proof_metadata" => {}, "created_at" => Time.utc(2025, 1, 1),
        "updated_at" => Time.utc(2025, 1, 1), "company_id" => company_id, "version" => 1, "generation" => 1,
        "enqueued_at" => enqueued_at, "sent_at" => sent_at
      }])
    end
    insert_row.call(1, now - 120)
    insert_row.call(1, now - 30)
    insert_row.call(1, now - 600, sent_at: now - 590)
    insert_row.call(2, now - 10)
    insert_row.call(3, now - 500, sent_at: now - 499)

    oldest = described_class.oldest_unsent_by_company

    expect(oldest.transform_values(&:to_i)).to eq(1 => (now - 120).to_i, 2 => (now - 10).to_i)
  end
end
